{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Grazoprevir, the closest analogue sharing the cyclopropyl acylsulfonamide P1, tert-leucine P3, and macrocyclic carbamate scaffold, has an absolute oral bioavailability of 27% in humans, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Grazoprevir at therapeutic multiple dosing (200 mg daily) showed bioavailability of 24–40%, reinforcing that the close analogue is above the threshold at clinically relevant doses.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "A single 25 mg grazoprevir dose gave bioavailability of 10–17%, indicating dose-dependent absorption; this is contradictory but less representative of therapeutic dosing.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "SCH 900518, a macrocyclic HCV protease inhibitor with the same P1 cyclopropyl acylsulfonamide, had a mean absolute bioavailability of 40.8%, supporting high F for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Simeprevir, another macrocyclic HCV protease inhibitor with a cyclopropyl acylsulfonamide, had an absolute bioavailability of 62%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Danoprevir, a less similar macrocyclic HCV protease inhibitor, had a bioavailability of only 1.15% due to first-pass metabolism and efflux; this is contradictory but has lower transferability and is outweighed by closer analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue grazoprevir has absolute F of 27% (24–40% at therapeutic doses), and other macrocyclic HCV protease inhibitors with the same P1 acylsulfonamide (simeprevir 62%, narlaprevir 40.8%) are high; the low F of danoprevir and the 25 mg grazoprevir data are less transferable or dose-specific. Thus F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule; prediction relies on analogues.",
    "Grazoprevir single-dose data show F below 20% at 25 mg, indicating dose-dependent absorption that could affect threshold classification.",
    "Danoprevir's very low F shows that macrocyclic HCV inhibitors can have poor F, so structural differences matter."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

